package com.iqbal.gurmukhikeyboard50
import java.math.BigInteger
object PunjabiNumberConverter { private val units = arrayOf("", "ਇੱਕ", "ਦੋ", "ਤਿੰਨ", "ਚਾਰ", "ਪੰਜ", "ਛੇ", "ਸੱਤ", "ਅੱਠ", "ਨੌ"); private val teens = arrayOf("ਦਸ", "ਗਿਆਰਾਂ", "ਬਾਰਾਂ", "ਤੇਰਾਂ", "ਚੌਦਾਂ", "ਪੰਦਰਾਂ", "ਸੋਲਾਂ", "ਸਤਾਰਾਂ", "ਅਠਾਰਾਂ", "ਉਨੀ"); private val tens = arrayOf("", "", "ਵੀਹ", "ਤੀਹ", "ਚਾਲੀ", "ਪੰਜਾਹ", "ਸੱਠ", "ਸੱਤਰ", "ਅੱਸੀ", "ਨੱਬੇ"); private val specialMap = mapOf(21 to "ਇੱਕੀ", 22 to "ਬਾਈ", 23 to "ਤੇਈ", 24 to "ਚੌਵੀ", 25 to "ਪੰਚੀ", 26 to "ਛੱਬੀ", 27 to "ਸਤਾਈ", 28 to "ਅਠਾਈ", 29 to "ਉਨੱਤੀ", 31 to "ਇਕੱਤੀ", 32 to "ਬੱਤੀ", 33 to "ਤੈਂਤੀ", 34 to "ਚੌਂਤੀ", 35 to "ਪੈਂਤੀ", 36 to "ਛੱਤੀ", 37 to "ਸੈਂਤੀ", 38 to "ਅਠੱਤੀ", 39 to "ਉਨਤਾਲੀ", 41 to "ਇਕਤਾਲੀ", 42 to "ਬਿਆਲੀ", 43 to "ਤਾਲੀ", 44 to "ਚੁਤਾਲੀ", 45 to "ਪੈਤਾਲੀ", 46 to "ਛਿਆਲੀ", 47 to "ਸੰਤਾਲੀ", 48 to "ਅਠਤਾਲੀ", 49 to "ਉਣਵੰਜਾ", 51 to "ਇਕਵੰਜਾ", 52 to "ਬਾਵੰਜਾ", 53 to "ਤਰਵੰਜਾ", 54 to "ਚੌਵੰਜਾ", 55 to "ਪਚਵੰਜਾ", 56 to "ਛਪੰਜਾ", 57 to "ਸਤਵੰਜਾ", 58 to "ਅਠਵੰਜਾ", 59 to "ਉਣਾਹਟ", 61 to "ਇਕਾਹਟ", 62 to "ਬਾਹਟ", 63 to "ਤਰੇਹਟ", 64 to "ਚੌਂਹਟ", 65 to "ਪੈਂਹਟ", 66 to "ਛਿਆਹਟ", 67 to "ਸਤਾਹਟ", 68 to "ਅਠਾਹਟ", 69 to "ਉਨੱਤਰ", 71 to "ਇਕੱਤਰ", 72 to "ਬਹੱਤਰ", 73 to "ਤਿਹੱਤਰ", 74 to "ਚੌਹੱਤਰ", 75 to "ਪਚੱਤਰ", 76 to "ਛਿਹੱਤਰ", 77 to "ਸਤੱਤਰ", 78 to "ਅਠੱਤਰ", 79 to "ਉਨਾਸੀ", 81 to "ਇਕਿਆਸੀ", 82 to "ਬਿਆਸੀ", 83 to "ਤਿਰਾਸੀ", 84 to "ਚੌਰਾਸੀ", 85 to "ਪਚਾਸੀ", 86 to "ਛਿਆਸੀ", 87 to "ਸਤਾਸੀ", 88 to "ਅਠਾਸੀ", 89 to "ਉਨਾਨਵੇਂ", 90 to "ਨੱਬੇ", 91 to "ਇਕਾਨਵੇਂ", 92 to "ਬਾਨਵੇਂ", 93 to "ਤਿਰਾਨਵੇਂ", 94 to "ਚੌਰਾਨਵੇਂ", 95 to "ਪਚਾਨਵੇਂ", 96 to "ਛਿਆਨਵੇਂ", 97 to "ਸਤਾਨਵੇਂ", 98 to "ਅਠਾਨਵੇਂ", 99 to "ਨੜਿੰਨਵੇਂ"); private val indianNames = arrayOf("", "ਹਜ਼ਾਰ", "ਲੱਖ", "ਕਰੋੜ", "ਅਰਬ", "ਖਰਬ", "ਨੀਲ", "ਪਦਮ", "ਸ਼ੰਖ", "ਮਹਾ-ਸ਼ੰਖ", "ਅੰਤ", "ਮਹਾ-ਅੰਤ", "ਮੱਧ", "ਪਰਾਰਧ"); private val THOUSAND = BigInteger.valueOf(1000); private val MILLION = BigInteger.valueOf(1000000); private val BILLION = BigInteger.valueOf(1000000000); private val TRILLION = BigInteger("1000000000000"); private val QUADRILLION = BigInteger("1000000000000000"); private val QUINTILLION = BigInteger("1000000000000000000")
fun convertToWords(numberStr: String, useInternational: Boolean = false): String { val cleanNumber = numberStr.replace(",", "").replace(" ", "").split(".")[0]; if (cleanNumber.isEmpty() || cleanNumber.length > 30) return ""; return try { val n = BigInteger(cleanNumber); if (n < BigInteger.valueOf(100)) return ""; val words = if (useInternational) convertInternational(n) else convertIndianLarge(cleanNumber); if (words.isEmpty() || words == "ਬਹੁਤ ਵੱਡੀ ਸੰਖਿਆ") "" else words.trim() + " ਰੁਪਏ ਮਾਤਰ" } catch (e: Exception) { "" } }
private fun convertIndianLarge(num: String): String { var s = num; if (s.length <= 3) return convertBelowThousand(s.toInt()); val result = StringBuilder(); val last3Str = s.substring(s.length - 3); val last3 = last3Str.toInt(); if (last3 > 0) result.append(convertBelowThousand(last3)); s = s.substring(0, s.length - 3); var unitIdx = 1; while (s.isNotEmpty()) { val take = if (s.length >= 2) 2 else 1; val part = s.substring(s.length - take).toInt(); if (part > 0) { val unitName = if (unitIdx < indianNames.size) indianNames[unitIdx] else ""; if (unitName.isNotEmpty()) result.insert(0, convertBelowThousand(part) + " " + unitName + " ") }; s = s.substring(0, s.length - take); unitIdx++ }; return result.toString() }
private fun convertBelowThousand(n: Int): String { if (n == 0) return ""; var res = ""; if (n >= 100) res += units[n / 100] + " ਸੌ "; val rem = n % 100; if (rem > 0) { if (rem < 10) res += units[rem] else if (rem < 20) res += teens[rem - 10] else res += specialMap[rem] ?: (tens[rem / 10] + " " + units[rem % 10]) }; return res }
private fun convertInternational(n: BigInteger): String { if (n == BigInteger.ZERO) return ""; fun join(high: BigInteger, unit: String, low: BigInteger): String { val left = convertInternational(high); val right = if (low == BigInteger.ZERO) "" else " " + convertInternational(low); return "$left $unit$right" }; return when { n < THOUSAND -> convertBelowThousand(n.toInt()); n < MILLION -> join(n / THOUSAND, "ਹਜ਼ਾਰ", n % THOUSAND); n < BILLION -> join(n / MILLION, "ਮਿਲੀਅਨ", n % MILLION); n < TRILLION -> join(n / BILLION, "ਬਿਲੀਅਨ", n % BILLION); n < QUADRILLION -> join(n / TRILLION, "ਟ੍ਰਿਲੀਅਨ", n % TRILLION); n < QUINTILLION -> join(n / QUADRILLION, "ਕਵਾਡ੍ਰਿਲੀਅਨ", n % QUADRILLION); else -> "ਬਹੁਤ ਵੱਡੀ ਸੰਖਿਆ" } } }
